'use strict';
/* TP/SL are local paper-order instructions; only Advance market evaluates exits. */
let protectionSide='Long',protectionPreview=null;
const protectionDraft=(s=symbol,side=protectionSide)=>chartPrefs.brackets?.[`${s}:${side}`]||{stop:null,target:null};
function protectionError(side,entry,stop,target){if(stop!==null&&(!Number.isFinite(stop)||stop<=0||(side==='Long'?stop>=entry:stop<=entry)))return `SL must be ${side==='Long'?'below':'above'} entry (${money(entry)}).`;if(target!==null&&(!Number.isFinite(target)||target<=0||(side==='Long'?target<=entry:target>=entry)))return `TP must be ${side==='Long'?'above':'below'} entry (${money(entry)}).`;return ''}
function currentProtection(){if(protectionPreview?.symbol===symbol)return {...protectionPreview,entry:protectionPreview.type==='Limit'?protectionPreview.entry:quote(symbol)};const d=protectionDraft();return {symbol,side:protectionSide,...d,entry:quote(symbol)}}
function chartProtectionLevels(){const levels=[];for(const p of state.positions.filter(p=>p.symbol===symbol)){levels.push({price:p.entry,type:'entry',label:`ENTRY · ${p.side} ${p.qty}`,position:p.id});if(p.stop)levels.push({price:p.stop,type:'sl',label:`SL · ${p.side} ${p.qty}`,position:p.id});if(p.target)levels.push({price:p.target,type:'tp',label:`TP · ${p.side} ${p.qty}`,position:p.id})}const d=currentProtection();if(!state.positions.some(p=>p.symbol===symbol&&p.side===d.side&&p.stop===d.stop&&p.target===d.target)&&!protectionError(d.side,d.entry,d.stop,d.target)){if(d.stop)levels.push({price:d.stop,type:'sl',label:'DRAFT SL',draft:true});if(d.target)levels.push({price:d.target,type:'tp',label:'DRAFT TP',draft:true})}return levels.filter(l=>Number.isFinite(l.price)&&l.price>0)}
const beforeProtectionGeometry=chartGeometry;
chartGeometry=function(){const g=beforeProtectionGeometry(),prices=chartProtectionLevels().map(l=>l.price);if(!prices.length)return g;const min=Math.min(g.min,...prices.map(p=>p*.9985)),max=Math.max(g.max,...prices.map(p=>p*1.0015));return {...g,min,max,y:p=>20+(max-p)/(max-min)*290}};
const beforeProtectionSVG=chartSVG;
chartSVG=function(){let svg=beforeProtectionSVG(),g=chartGeometry();const overlay=chartProtectionLevels().map(l=>{const color=l.type==='sl'?'#ff7187':l.type==='tp'?'#63d9ad':'#86a9e8',y=g.y(l.price);return `<g ${l.position?`data-position-protection="${l.position}"`:'data-draft-protection="true"'} class="protection-chart-level" style="cursor:pointer"><line x1="8" x2="830" y1="${y}" y2="${y}" stroke="${color}" stroke-width="1.2" stroke-dasharray="${l.draft?'3 5':'8 4'}" opacity="${l.draft?'.65':'.95'}"/><line x1="8" x2="830" y1="${y}" y2="${y}" stroke="transparent" stroke-width="13"/><text x="27" y="${y-6}" fill="${color}" font-size="10">${esc(l.label)} · ${l.price.toFixed(2)}${l.type==='entry'?'':' · edit'}</text></g>`}).join('');return svg.replace('</svg>',`<g clip-path="url(#chartClip)">${overlay}</g></svg>`)};
function refreshProtectionChart(){const frame=$('.chart-frame');if(!frame||page!=='chart')return;frame.querySelector('svg').outerHTML=chartSVG();$$('.oscillator-pane').forEach(p=>{const id=$('[data-remove-study]',p)?.dataset.removeStudy;if(id)p.querySelector('svg').outerHTML=oscillatorSVG(id)});bindTerminalSizing();updateProtectionButtons()}
function updateProtectionButtons(){const d=currentProtection();for(const [id,key]of[['quickTP','target'],['quickSL','stop']]){const b=$('#'+id);if(b){b.classList.toggle('has-price',d[key]!==null);b.innerHTML=`<span>${id==='quickTP'?'TP':'SL'}</span><strong>${d[key]?Number(d[key]).toFixed(2):'ADD'}</strong>`}}const side=$('#protectionSideTag');if(side)side.textContent=d.side.toUpperCase()}
function protectionModal(focus='target',positionId){const position=positionId?state.positions.find(p=>p.id===positionId):null,activeForm=$('#orderForm'),preview=currentProtection(),draft=position||preview,entry=position?.entry||preview.entry||quote(symbol);const d=openModal(position?`${position.symbol} / Edit TP & SL`:`${symbol} / Take Profit & Stop Loss`,`<form id="protectionForm"><div class="notice">${position?'Updates an existing simulated position. Exits are checked only when you advance the paper market.':'Draft levels only. A paper order still requires review and confirmation.'}</div><div class="form-grid"><div class="form-group"><label for="protectionDirection">Direction</label><select id="protectionDirection" name="side" ${position?'disabled':''}><option ${draft.side==='Long'?'selected':''}>Long</option><option ${draft.side==='Short'?'selected':''}>Short</option></select></div><div class="form-group"><label>Reference entry</label><div class="protection-entry number">${money(entry)}</div></div><div class="form-group"><label for="protectionTarget" class="up">TP · Take Profit ($)</label><input id="protectionTarget" name="target" type="number" min=".01" step=".01" placeholder="Optional" value="${draft.target??''}"></div><div class="form-group"><label for="protectionStop" class="down">SL · Stop Loss ($)</label><input id="protectionStop" name="stop" type="number" min=".01" step=".01" placeholder="Optional" value="${draft.stop??''}"></div></div><div id="protectionRisk" class="order-summary"></div><p class="error" id="protectionError" role="alert"></p><div class="head-actions"><button class="btn" type="button" id="clearProtection">Clear both</button><button class="btn primary" type="submit">${position?'Update position':'Apply TP / SL'}</button></div></form>`);const form=$('#protectionForm',d);const read=()=>({side:position?.side||form.elements.namedItem('side').value,stop:form.elements.namedItem('stop').value?Number(form.elements.namedItem('stop').value):null,target:form.elements.namedItem('target').value?Number(form.elements.namedItem('target').value):null});const update=()=>{const v=read(),q=position?.qty||Number($('#quickQuantity')?.value||activeForm?.elements.namedItem('qty').value||10),risk=v.stop?Math.abs(entry-v.stop)*q:null,reward=v.target?Math.abs(v.target-entry)*q:null;$('#protectionError',d).textContent=protectionError(v.side,entry,v.stop,v.target);$('#protectionRisk',d).innerHTML=`<div class="kv"><span>Quantity</span><strong>${q} shares</strong></div><div class="kv"><span>Risk to SL</span><strong class="number down">${risk!==null?money(risk):'Not set'}</strong></div><div class="kv"><span>Reward to TP</span><strong class="number up">${reward!==null?money(reward):'Not set'}</strong></div><div class="kv"><span>Reward / risk</span><strong>${risk&&reward?(reward/risk).toFixed(2)+'R':'—'}</strong></div>`};form.oninput=update;form.onchange=update;$('#clearProtection',d).onclick=()=>{form.elements.namedItem('target').value='';form.elements.namedItem('stop').value='';update()};form.onsubmit=e=>{e.preventDefault();const v=read(),err=protectionError(v.side,entry,v.stop,v.target);if(err){$('#protectionError',d).textContent=err;return}if(position){position.stop=v.stop;position.target=v.target;save();closeModal();render();toast('Paper position TP / SL updated.');return}protectionSide=v.side;chartPrefs.brackets||={};chartPrefs.brackets[`${symbol}:${v.side}`]={stop:v.stop,target:v.target};saveChart();protectionPreview={symbol,entry,...v};closeModal();const ticket=$('#orderForm');if(ticket){ticket.elements.namedItem('side').value=v.side;ticket.elements.namedItem('stop').value=v.stop??'';ticket.elements.namedItem('target').value=v.target??'';ticket.dispatchEvent(new Event('input'))}refreshProtectionChart();toast('Draft TP / SL applied. Review a paper order to place it.')};update();setTimeout(()=>{if(d.open)$(focus==='stop'?'#protectionStop':'#protectionTarget',d)?.focus()},30)}
const beforeProtectionAction=action;
action=function(value){if(value==='protection-tp'||value==='protection-sl'){protectionModal(value==='protection-tp'?'target':'stop');return}if(value==='chart-buy'||value==='chart-sell'){protectionSide=value==='chart-buy'?'Long':'Short';protectionPreview=null;beforeProtectionAction(value);const form=$('#orderForm');if(form){const d=protectionDraft(symbol,protectionSide);form.elements.namedItem('stop').value=d.stop??'';form.elements.namedItem('target').value=d.target??'';form.dispatchEvent(new Event('input'))}return}beforeProtectionAction(value)};
const beforeProtectionBind=bindPage;
bindPage=function(){beforeProtectionBind();if(page==='chart'){const bar=$('.quick-trade-bar');if(bar){bar.insertAdjacentHTML('beforeend',`<div class="quick-protection"><span id="protectionSideTag">${protectionSide.toUpperCase()}</span><button id="quickTP" data-action="protection-tp" aria-label="Set Take Profit"></button><button id="quickSL" data-action="protection-sl" aria-label="Set Stop Loss"></button></div>`);bindActions($('.quick-protection'));updateProtectionButtons()}const frame=$('.chart-frame');if(frame){let hit=null;frame.addEventListener('pointerdown',e=>{const pos=e.target.closest('[data-position-protection]'),draft=e.target.closest('[data-draft-protection]');if(pos||draft){hit={id:pos?.dataset.positionProtection,x:e.clientX,y:e.clientY};frame.setPointerCapture(e.pointerId);e.stopImmediatePropagation()}},true);frame.addEventListener('pointerup',e=>{if(!hit)return;const h=hit;hit=null;e.stopImmediatePropagation();if(Math.abs(e.clientX-h.x)+Math.abs(e.clientY-h.y)<10)protectionModal('target',h.id)},true)}}const form=$('#orderForm');if(form){const sl=$('label[for="orderStop"]',form),tp=$('label[for="orderTarget"]',form);if(sl){sl.textContent='SL · Stop Loss ($)';sl.classList.add('down')}if(tp){tp.textContent='TP · Take Profit ($)';tp.classList.add('up')}form.insertAdjacentHTML('beforeend','<p class="protection-ticket-note">TP / SL are evaluated at the simulated quote when you advance the paper market.</p>');const oldInput=form.oninput,oldChange=form.onchange;const update=()=>{const side=form.elements.namedItem('side').value,s=form.elements.namedItem('symbol').value,entry=form.elements.namedItem('type').value==='Limit'?Number(form.elements.namedItem('limit').value):quote(s),stop=form.elements.namedItem('stop').value?Number(form.elements.namedItem('stop').value):null,target=form.elements.namedItem('target').value?Number(form.elements.namedItem('target').value):null;protectionSide=side;protectionPreview={symbol:s,side,entry,stop,target,type:form.elements.namedItem('type').value};const old=$('#protectionTicketRisk',form);old?.remove();const err=protectionError(side,entry,stop,target);if(!err){chartPrefs.brackets||={};chartPrefs.brackets[`${s}:${side}`]={stop,target};saveChart()}const qty=Number(form.elements.namedItem('qty').value),risk=stop?Math.abs(entry-stop)*qty:null,reward=target?Math.abs(target-entry)*qty:null;$('#ticketEstimate',form).insertAdjacentHTML('beforeend',`<div id="protectionTicketRisk">${reward!==null?`<div class="kv"><span>Reward to TP</span><strong class="number up">${money(reward)}</strong></div>`:''}${risk&&reward?`<div class="kv"><span>Reward / risk</span><strong>${(reward/risk).toFixed(2)}R</strong></div>`:''}${err?`<div class="error">${err}</div>`:''}</div>`);refreshProtectionChart()};form.oninput=e=>{oldInput?.(e);update()};form.onchange=e=>{oldChange?.(e);update()};if(page==='chart'){const d=protectionDraft();form.elements.namedItem('side').value=protectionSide;form.elements.namedItem('stop').value=d.stop??'';form.elements.namedItem('target').value=d.target??'';form.dispatchEvent(new Event('input'))}}$$('[data-close-position]').forEach(b=>{const p=state.positions.find(p=>p.id===b.dataset.closePosition);if(p){const edit=document.createElement('button');edit.className='btn small position-protection-edit';edit.textContent='TP / SL';edit.setAttribute('aria-label',`Edit ${p.symbol} position TP and SL`);edit.onclick=()=>protectionModal('target',p.id);b.parentElement.prepend(edit)}})};
window.addEventListener('frye:reset',()=>{protectionPreview=null;protectionSide='Long'});
render();
